contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        uint beforeBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBalance = address(c).balance;

        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint afterBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBalance = address(c).balance;

        assert(afterBalance >= beforeBalance && afterBalance - beforeBalance == depositAmount &&
               afterContractBalance >= beforeContractBalance && afterContractBalance - beforeContractBalance == depositAmount);
    }

    receive() external payable {}
}

